 <button class="btn b-pr" data-id="login" ${A(()=>{const e={le:!emailOk(S.f.le),lp:S.f.lp.length<8};if(e.le||e.lp)set({errs:e});else{S.email=S.f.le;loginOk()}})}>${L('دخول','Log in')}</button>
