 <button class="btn b-pr" data-id="signup" ${A(()=>{const pw=S.f.sp;const e={sn:!S.f.sn.trim(),se:!emailOk(S.f.se),sp:!(pw.length>=8&&/\d/.test(pw)&&/\D/.test(pw)),sp2:!S.f.sp2||S.f.sp2!==pw};if(Object.values(e).some(Boolean))set({errs:e});else{S.name=S.f.sn.trim().split(' ')[0];S.email=S.f.se;loginOk()}})}>${L('إنشاء الحساب','Create account')}</button>
