const API=window.MASHI_API;
const csrf=()=>{const m=document.cookie.match(/(?:^|;\s*)csrftoken=([^;]+)/);return m?decodeURIComponent(m[1]):''};
async function api(path,form){const o={method:form?'POST':'GET',headers:{'X-CSRFToken':csrf(),'Accept':'application/json'},credentials:'same-origin'};
 if(form){const b=new URLSearchParams();Object.entries(form).forEach(([k,v])=>{if(Array.isArray(v))v.forEach(x=>b.append(k,x));else if(v!=null)b.append(k,v)});o.body=b}
 const r=await fetch(API.base+path,o);let j={};try{j=await r.json()}catch(e){}if(!r.ok){const e=new Error(j.error||('HTTP '+r.status));e.data=j;e.status=r.status;throw e}return j}
const B={ready:false,ints:[],pavs:[],by:{},plan:null,ch:null,pass:null,passCode:null,loc:{},busy:false,demo:true};S.be=B;S.bInts={};S.bFav={};S.bq='';S.bcat='all';
