function applyDoc(){const r=document.documentElement;r.lang=S.lang;r.dir=EN()?'ltr':'rtl';r.classList.toggle('dk',S.appearance==='dark');r.classList.toggle('lt',S.appearance==='light');const dark=S.appearance==='dark'||(S.appearance==='auto'&&(r.getAttribute('data-theme')==='dark'||(!r.getAttribute('data-theme')&&matchMedia('(prefers-color-scheme: dark)').matches)));const m=document.querySelector('meta[name=theme-color]');if(m)m.content=dark?'#041C17':'#F7FAF8'}
let focusKey=null;
